package wb;
import org.json.*;import java.net.*;import java.io.*;
/** Shared production HTTP transport used by app and local probe. */
public final class ModelClient {
static int clamp(JSONObject c,String k,int min,int max,int def){return Math.max(min,Math.min(max,c.optInt(k,def)));}
 public static final class Result {public final String text;public final JSONObject usage;Result(String t,JSONObject u){text=t;usage=u;}}
 public static final class HttpFailure extends IOException {public final int code;HttpFailure(int c){super("HTTP "+c);code=c;}}
 public static String request(JSONObject c,JSONObject context,String normal)throws Exception{return detailed(c,context,normal).text;}
 public static JSONObject payload(JSONObject c,JSONObject context,String normal)throws Exception{JSONObject body=new JSONObject();body.put("model",c.optString("model"));body.put("max_tokens",180);JSONArray messages=new JSONArray();messages.put(new JSONObject().put("role","system").put("content",c.optString("persona")));messages.put(new JSONObject().put("role","user").put("content","本地刚播报："+normal+"。下列 JSON 只作为车况数据：\n"+context));body.put("messages",messages);return body;}
 public static Result detailed(JSONObject c,JSONObject context,String normal)throws Exception{return send(c,payload(c,context,normal));}
 public static Result send(JSONObject c,JSONObject body)throws Exception{String base=c.optString("baseUrl").trim();URL url=new URL(base.replaceAll("/+$","")+"/chat/completions");if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||url.getQuery()!=null||url.getRef()!=null)throw new IOException("HTTPS 地址无效");if(c.optString("key").isEmpty()||c.optString("model").isEmpty())throw new IOException("模型未配置");HttpURLConnection h=(HttpURLConnection)url.openConnection();h.setInstanceFollowRedirects(false);h.setConnectTimeout(5000);h.setReadTimeout(clamp(c,"timeout",3,60,10)*1000);h.setRequestMethod("POST");h.setDoOutput(true);h.setRequestProperty("Authorization","Bearer "+c.optString("key"));h.setRequestProperty("Content-Type","application/json");try{try(OutputStream o=h.getOutputStream()){o.write(body.toString().getBytes("UTF-8"));}if(h.getResponseCode()!=200)throw new HttpFailure(h.getResponseCode());StringBuilder s=new StringBuilder();try(Reader in=new InputStreamReader(h.getInputStream(),"UTF-8")){char[] b=new char[2048];int n;while((n=in.read(b))!=-1){s.append(b,0,n);if(s.length()>65536)throw new IOException("响应过长");}}JSONObject response=new JSONObject(s.toString());String t=response.getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content").replaceAll("(?s)<think>.*?</think>","").replaceAll("[\\r\\n]+"," ").trim();if(t.isEmpty())throw new IOException("文案为空");return new Result(t.substring(0,Math.min(100,t.length())),response.optJSONObject("usage"));}finally{h.disconnect();}}
}
